import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import os

sns.set_theme(style="whitegrid")

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# 2. Clean Data
def clean_currency(x):
    if isinstance(x, str):
        return x.replace('₹', '').replace(',', '').strip()
    return x

df['discounted_price'] = pd.to_numeric(df['discounted_price'].apply(clean_currency), errors='coerce')
df['actual_price'] = pd.to_numeric(df['actual_price'].apply(clean_currency), errors='coerce')
df['discount_percentage'] = pd.to_numeric(df['discount_percentage'].astype(str).str.replace('%', ''), errors='coerce')
df['rating'] = pd.to_numeric(df['rating'], errors='coerce')
df['rating_count'] = pd.to_numeric(df['rating_count'].astype(str).str.replace(',', ''), errors='coerce')
df['main_category'] = df['category'].astype(str).apply(lambda x: x.split('|')[0] if pd.notnull(x) else 'Unknown')

# Drop completely empty rows just in case
df = df.dropna(subset=['product_id'])

# 3. KPIs Calculation
total_products = len(df)
avg_rating = df['rating'].mean()
avg_discount = df['discount_percentage'].mean()
med_rating_count = df['rating_count'].median()
high_rating_share = (len(df[df['rating'] >= 4.0]) / len(df['rating'].dropna())) * 100
discount_rating_corr = df['discount_percentage'].corr(df['rating'])

# 4. Helper for Base64 Images
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# 5. Visualizations
charts = {}

# Chart 1: Category Performance (Rating)
cat_stats = df.groupby('main_category').agg({
    'rating': 'mean',
    'discount_percentage': 'mean',
    'rating_count': 'mean',
    'product_id': 'count'
}).reset_index().rename(columns={'product_id': 'product_count'})
cat_stats = cat_stats[cat_stats['product_count'] > 5].sort_values('rating', ascending=False)

fig1, ax1 = plt.subplots(figsize=(10, 6))
sns.barplot(data=cat_stats, y='main_category', x='rating', palette='viridis', ax=ax1)
ax1.set_title('Average Customer Rating by Category')
ax1.set_xlabel('Average Rating')
ax1.set_ylabel('Main Category')
charts['cat_rating'] = fig_to_base64(fig1)

# Chart 2: Category Performance (Discount)
cat_stats = cat_stats.sort_values('discount_percentage', ascending=False)
fig2, ax2 = plt.subplots(figsize=(10, 6))
sns.barplot(data=cat_stats, y='main_category', x='discount_percentage', palette='mako', ax=ax2)
ax2.set_title('Average Discount Percentage by Category')
ax2.set_xlabel('Discount Percentage (%)')
ax2.set_ylabel('Main Category')
charts['cat_discount'] = fig_to_base64(fig2)

# Chart 3: Pricing & Discount Analysis
fig3, ax3 = plt.subplots(figsize=(8, 6))
sns.scatterplot(data=df, x='discount_percentage', y='rating', alpha=0.5, ax=ax3, color='#4472C4')
ax3.set_title('Discount Percentage vs. Customer Rating')
ax3.set_xlabel('Discount Percentage (%)')
ax3.set_ylabel('Rating')
charts['scatter_discount_rating'] = fig_to_base64(fig3)

# Chart 4: Rating Distribution
fig4, ax4 = plt.subplots(figsize=(8, 6))
sns.histplot(data=df, x='rating', bins=20, kde=True, color='#2CA02C', ax=ax4)
ax4.set_title('Distribution of Customer Ratings')
ax4.set_xlabel('Rating')
ax4.set_ylabel('Frequency')
charts['rating_dist'] = fig_to_base64(fig4)

# 6. Sentiment Analysis Snapshot
reviews = df['review_title'].astype(str) + " " + df['review_content'].astype(str)
reviews_lower = reviews.str.lower()

pos_words = ['good', 'great', 'excellent', 'best', 'love', 'nice', 'perfect', 'awesome', 'value']
neg_words = ['bad', 'poor', 'worst', 'broken', 'slow', 'disappointed', 'waste', 'defective', 'terrible']

pos_counts = {w: reviews_lower.str.contains(r'\b' + w + r'\b', regex=True).sum() for w in pos_words}
neg_counts = {w: reviews_lower.str.contains(r'\b' + w + r'\b', regex=True).sum() for w in neg_words}

pos_df = pd.DataFrame(list(pos_counts.items()), columns=['Word', 'Count']).sort_values('Count', ascending=False)
neg_df = pd.DataFrame(list(neg_counts.items()), columns=['Word', 'Count']).sort_values('Count', ascending=False)

fig5, (ax5a, ax5b) = plt.subplots(1, 2, figsize=(12, 5))
sns.barplot(data=pos_df.head(5), x='Count', y='Word', palette='Greens_r', ax=ax5a)
ax5a.set_title('Top Positive Keywords')
sns.barplot(data=neg_df.head(5), x='Count', y='Word', palette='Reds_r', ax=ax5b)
ax5b.set_title('Top Negative Keywords')
plt.tight_layout()
charts['sentiment'] = fig_to_base64(fig5)

# 7. Generate HTML
html_content = f"""
<!DOCTYPE html>
<html lang="en">
<head>
